<?php
require_once __DIR__.'/config.php';$id=valid_id($_GET['id']??0);$stmt=$pdo->prepare("SELECT q.*,u.name author,s.name subject_name FROM questions q JOIN users u ON u.id=q.user_id LEFT JOIN subjects s ON s.id=q.subject_id WHERE q.id=? AND q.status='visible'");$stmt->execute([$id]);$q=$stmt->fetch();if(!$q){http_response_code(404);$pageTitle='Question not found';require __DIR__.'/includes/header.php';echo '<div class="container page-content"><div class="empty-state"><h2>Question not found</h2><a class="btn btn-primary" href="forum.php">Back to forum</a></div></div>';require __DIR__.'/includes/footer.php';exit;}
if(is_post()){require_login();verify_csrf();$body=posted_string('body',5000);if(mb_strlen($body)<5)set_flash('error','Answer must be at least 5 characters.');else{$pdo->prepare("INSERT INTO answers(question_id,user_id,body,status) VALUES(?,?,?,'visible')")->execute([$id,current_user()['id'],$body]);set_flash('success','Your answer has been added.');}redirect('question.php?id='.$id);}
$ans=$pdo->prepare("SELECT a.*,u.name author FROM answers a JOIN users u ON u.id=a.user_id WHERE a.question_id=? AND a.status='visible' ORDER BY a.created_at ASC");$ans->execute([$id]);$answers=$ans->fetchAll();$pageTitle=$q['title'];require __DIR__.'/includes/header.php';?>
<section class="page-hero"><div class="container"><a href="forum.php">← Back to forum</a><div class="mt-2"><span class="eyebrow"><?= e($q['subject_name']??'General') ?></span><h1><?= e($q['title']) ?></h1><p>Asked by <?= e($q['author']) ?> · <?= e(date('M j, Y',strtotime($q['created_at']))) ?></p></div></div></section><div class="page-content"><div class="container detail-layout"><div class="content-stack"><article class="panel"><p class="detail-content"><?= e($q['body']) ?></p></article><section class="panel"><h2><?= count($answers) ?> answer<?= count($answers)===1?'':'s' ?></h2><?php if($answers): foreach($answers as $a): ?><article class="card answer-card"><strong><?= e($a['author']) ?></strong><span class="small-muted"> · <?= e(date('M j, Y',strtotime($a['created_at']))) ?></span><p class="detail-content mt-1"><?= e($a['body']) ?></p></article><?php endforeach; else: ?><p>No answers yet. Your explanation could help someone.</p><?php endif; ?></section></div><aside class="panel"><h3>Share your knowledge</h3><?php if(current_user()): ?><form method="post"><?= csrf_field() ?><div class="form-group"><label for="body">Your answer</label><textarea id="body" name="body" required maxlength="5000" placeholder="Explain your approach clearly…"></textarea></div><button class="btn btn-primary btn-block">Post answer</button></form><?php else: ?><p><a href="login.php">Log in</a> to answer this question.</p><?php endif; ?></aside></div></div><?php require __DIR__.'/includes/footer.php';?>
